insert into note_templates (id, doctor_id, name, body) values
  ('00000016-0000-4000-8000-000000000001', null, 'Upper respiratory infection', '{"chief_complaint":"Fever, sore throat and runny nose","history":"Duration __ days. No breathlessness, chest pain or ear discharge.","examination":"Comfortable on video, speaking full sentences. Throat congested on self-examination with torch.","advice":"Warm saline gargles, steam inhalation, plenty of fluids, rest. Review if fever persists beyond 3 days or if breathing becomes difficult.","investigations":"","diagnoses":[{"code":"J06.9","description":"Acute upper respiratory infection, unspecified"}]}'::jsonb),
  ('00000016-0000-4000-8000-000000000002', null, 'Acute gastroenteritis', '{"chief_complaint":"Loose stools and vomiting","history":"Episodes per day: __. No blood in stools. Passing urine normally.","examination":"Alert, oral intake possible. No signs of severe dehydration reported.","advice":"ORS after every loose stool, light diet, hand hygiene. Go to the emergency department for blood in stools, drowsiness or no urine for 8 hours.","investigations":"Stool routine if not better in 48 hours","diagnoses":[{"code":"A09","description":"Infectious gastroenteritis and colitis, unspecified"}]}'::jsonb),
  ('00000016-0000-4000-8000-000000000003', null, 'Hypertension follow-up', '{"chief_complaint":"Review of blood pressure","history":"Home BP readings: __. Adherence to medicines: good. No headache, chest pain or breathlessness.","examination":"Home BP log reviewed. No pedal oedema reported.","advice":"Low salt diet, 30 minutes brisk walk daily, continue home BP log.","investigations":"Lipid profile, serum creatinine, ECG","diagnoses":[{"code":"I10","description":"Essential (primary) hypertension"}]}'::jsonb),
  ('00000016-0000-4000-8000-000000000004', null, 'Type 2 diabetes review', '{"chief_complaint":"Review of blood sugar","history":"Fasting sugar readings: __. No hypoglycaemia episodes. Diet and exercise discussed.","examination":"Foot self-check reviewed on video: no ulcers.","advice":"Diabetic diet, regular walking, foot care, monitor fasting sugar thrice weekly.","investigations":"HbA1c, fasting and post-prandial blood sugar, urine microalbumin","diagnoses":[{"code":"E11.9","description":"Type 2 diabetes mellitus without complications"}]}'::jsonb),
  ('00000016-0000-4000-8000-000000000005', null, 'Allergic rhinitis', '{"chief_complaint":"Sneezing and blocked nose","history":"Seasonal / perennial. Triggers: dust, cold air.","examination":"No breathlessness or wheeze reported.","advice":"Avoid known triggers, saline nasal rinse, keep bedroom dust-free.","investigations":"","diagnoses":[{"code":"J30.4","description":"Allergic rhinitis, unspecified"}]}'::jsonb),
  ('00000016-0000-4000-8000-000000000006', null, 'Acid peptic disease', '{"chief_complaint":"Burning upper abdominal pain","history":"Related to meals. No vomiting of blood, black stools or weight loss.","examination":"Comfortable on video.","advice":"Small frequent meals, avoid spicy food, late-night meals and smoking. Go to the emergency department for black stools or vomiting blood.","investigations":"","diagnoses":[{"code":"K21.9","description":"Gastro-oesophageal reflux disease without oesophagitis"}]}'::jsonb),
  ('00000016-0000-4000-8000-000000000007', null, 'Low back pain', '{"chief_complaint":"Lower back pain","history":"Onset after __. No leg weakness, numbness or bladder / bowel problems.","examination":"Walking independently on video. Able to bend forward with mild discomfort.","advice":"Stay active, avoid heavy lifting, back extension exercises, hot fomentation.","investigations":"","diagnoses":[{"code":"M54.5","description":"Low back pain"}]}'::jsonb),
  ('00000016-0000-4000-8000-000000000008', null, 'Urinary tract infection', '{"chief_complaint":"Burning while passing urine","history":"Frequency and urgency for __ days. No fever, flank pain or vomiting.","examination":"Comfortable on video.","advice":"Drink plenty of water, do not hold urine. See a doctor in person for fever, back pain or blood in urine.","investigations":"Urine routine and culture","diagnoses":[{"code":"N39.0","description":"Urinary tract infection, site not specified"}]}'::jsonb),
  ('00000016-0000-4000-8000-000000000009', null, 'Tension-type headache', '{"chief_complaint":"Headache","history":"Band-like, both sides, no vomiting, no visual disturbance, no weakness.","examination":"Alert and oriented on video, speech normal.","advice":"Regular sleep, screen breaks, hydration. Seek urgent care for sudden severe headache, weakness or confusion.","investigations":"","diagnoses":[{"code":"G44.2","description":"Tension-type headache"}]}'::jsonb);
