insert into app_settings (key, value) values
  ('consult_minutes', '15'::jsonb),
  ('slot_hold_minutes', '10'::jsonb),
  ('join_window_minutes', '10'::jsonb),
  ('doctor_grace_minutes', '10'::jsonb),
  ('patient_grace_minutes', '10'::jsonb),
  ('auto_doctor_no_show_minutes', '30'::jsonb),
  ('auto_patient_no_show_minutes', '30'::jsonb),
  ('cancellation_tiers', '[{"min_hours_before":2,"percent":100},{"min_hours_before":0,"percent":0}]'::jsonb),
  ('patient_no_show_refund_percent', '0'::jsonb),
  ('patient_reschedule_min_hours', '2'::jsonb),
  ('doctor_no_show_auto_refund_hours', '24'::jsonb),
  ('patient_reschedule_limit', '1'::jsonb),
  ('max_upload_mb', '10'::jsonb),
  ('join_close_minutes', '30'::jsonb),
  ('recording_enabled', 'false'::jsonb),
  ('allowed_upload_types', '["application/pdf","image/jpeg","image/png"]'::jsonb),
  ('consent_versions', '{"teleconsultation":"1.0","data_processing":"1.0","whatsapp_opt_in":"1.0","terms":"1.0","marketing":"1.0"}'::jsonb),
  ('consent_texts', '{"teleconsultation":{"en":"I consent to receive medical consultation by audio/video from a Sunrise registered medical practitioner. I understand that teleconsultation has limitations, that the doctor may advise an in-person visit, and that this service is not for emergencies.","ml":"സൺറൈസ് രജിസ്റ്റേർഡ് ഡോക്ടറിൽ നിന്ന് ഓഡിയോ/വീഡിയോ വഴി ചികിത്സാ കൺസൾട്ടേഷൻ സ്വീകരിക്കാൻ ഞാൻ സമ്മതിക്കുന്നു. ടെലികൺസൾട്ടേഷന് പരിമിതികളുണ്ടെന്നും ഡോക്ടർ നേരിട്ട് കാണാൻ നിർദ്ദേശിച്ചേക്കാമെന്നും ഇത് അടിയന്തര സേവനമല്ലെന്നും ഞാൻ മനസ്സിലാക്കുന്നു."},"data_processing":{"en":"I consent to Sunrise Chain of Hospitals processing my personal and health data (and that of family members I add) to provide consultations, prescriptions and records, as described in the Privacy Notice. I can withdraw consent or request erasure at any time.","ml":"കൺസൾട്ടേഷൻ, കുറിപ്പടി, രേഖകൾ എന്നിവ നൽകുന്നതിനായി എന്റെയും ഞാൻ ചേർക്കുന്ന കുടുംബാംഗങ്ങളുടെയും വ്യക്തിഗത, ആരോഗ്യ വിവരങ്ങൾ സ്വകാര്യതാ അറിയിപ്പിൽ പറയുന്ന പ്രകാരം സൺറൈസ് ഉപയോഗിക്കുന്നതിന് ഞാൻ സമ്മതിക്കുന്നു. എപ്പോൾ വേണമെങ്കിലും സമ്മതം പിൻവലിക്കാം."},"whatsapp_opt_in":{"en":"Send me appointment updates and secure links on WhatsApp. Messages never contain medical details.","ml":"അപ്പോയിന്റ്മെന്റ് വിവരങ്ങളും സുരക്ഷിത ലിങ്കുകളും വാട്ട്‌സ്ആപ്പിൽ അയയ്ക്കുക. സന്ദേശങ്ങളിൽ ചികിത്സാ വിവരങ്ങൾ ഉണ്ടാകില്ല."},"terms":{"en":"I agree to the Terms of Use, Refund Policy and Privacy Notice of Sunrise Care Connect.","ml":"സൺറൈസ് കെയർ കണക്റ്റിന്റെ ഉപയോഗ നിബന്ധനകൾ, റീഫണ്ട് നയം, സ്വകാര്യതാ അറിയിപ്പ് എന്നിവ ഞാൻ അംഗീകരിക്കുന്നു."},"marketing":{"en":"Sunrise may contact me (call, SMS or WhatsApp) about its health services and camps. Only my name, mobile number and city are used – never my medical details. I can withdraw this at any time.","ml":"സൺറൈസിന്റെ ആരോഗ്യ സേവനങ്ങളെയും ക്യാമ്പുകളെയും കുറിച്ച് എന്നെ ബന്ധപ്പെടാം (കോൾ, SMS, WhatsApp). എന്റെ പേര്, മൊബൈൽ നമ്പർ, നഗരം എന്നിവ മാത്രം – ചികിത്സാ വിവരങ്ങൾ ഒരിക്കലുമില്ല. എപ്പോൾ വേണമെങ്കിലും പിൻവലിക്കാം."}}'::jsonb),
  ('abdm_enabled', 'false'::jsonb),
  ('integrations', '{"his":false,"leadsquared":false}'::jsonb),
  ('support_phone', '"+914842000100"'::jsonb),
  ('grievance_officer', '{"name":"Grievance Officer, Sunrise Chain of Hospitals","email":"grievance@sunrisehospitals.example","phone":"+914842000199"}'::jsonb),
  ('notification_costs', '{"whatsapp":13,"sms":25,"push":0}'::jsonb),
  ('notification_quiet_hours', '{"start":"21:00","end":"08:00"}'::jsonb),
  ('feedback_delay_minutes', '120'::jsonb);
insert into content_versions (key, version, revision, title_en, title_ml, body_en, body_ml, reason) values
  ('teleconsultation', '1.0', 1, '', '', 'I consent to receive medical consultation by audio/video from a Sunrise registered medical practitioner. I understand that teleconsultation has limitations, that the doctor may advise an in-person visit, and that this service is not for emergencies.', 'സൺറൈസ് രജിസ്റ്റേർഡ് ഡോക്ടറിൽ നിന്ന് ഓഡിയോ/വീഡിയോ വഴി ചികിത്സാ കൺസൾട്ടേഷൻ സ്വീകരിക്കാൻ ഞാൻ സമ്മതിക്കുന്നു. ടെലികൺസൾട്ടേഷന് പരിമിതികളുണ്ടെന്നും ഡോക്ടർ നേരിട്ട് കാണാൻ നിർദ്ദേശിച്ചേക്കാമെന്നും ഇത് അടിയന്തര സേവനമല്ലെന്നും ഞാൻ മനസ്സിലാക്കുന്നു.', 'Initial text'),
  ('data_processing', '1.0', 1, '', '', 'I consent to Sunrise Chain of Hospitals processing my personal and health data (and that of family members I add) to provide consultations, prescriptions and records, as described in the Privacy Notice. I can withdraw consent or request erasure at any time.', 'കൺസൾട്ടേഷൻ, കുറിപ്പടി, രേഖകൾ എന്നിവ നൽകുന്നതിനായി എന്റെയും ഞാൻ ചേർക്കുന്ന കുടുംബാംഗങ്ങളുടെയും വ്യക്തിഗത, ആരോഗ്യ വിവരങ്ങൾ സ്വകാര്യതാ അറിയിപ്പിൽ പറയുന്ന പ്രകാരം സൺറൈസ് ഉപയോഗിക്കുന്നതിന് ഞാൻ സമ്മതിക്കുന്നു. എപ്പോൾ വേണമെങ്കിലും സമ്മതം പിൻവലിക്കാം.', 'Initial text'),
  ('whatsapp_opt_in', '1.0', 1, '', '', 'Send me appointment updates and secure links on WhatsApp. Messages never contain medical details.', 'അപ്പോയിന്റ്മെന്റ് വിവരങ്ങളും സുരക്ഷിത ലിങ്കുകളും വാട്ട്‌സ്ആപ്പിൽ അയയ്ക്കുക. സന്ദേശങ്ങളിൽ ചികിത്സാ വിവരങ്ങൾ ഉണ്ടാകില്ല.', 'Initial text'),
  ('terms', '1.0', 1, '', '', 'I agree to the Terms of Use, Refund Policy and Privacy Notice of Sunrise Care Connect.', 'സൺറൈസ് കെയർ കണക്റ്റിന്റെ ഉപയോഗ നിബന്ധനകൾ, റീഫണ്ട് നയം, സ്വകാര്യതാ അറിയിപ്പ് എന്നിവ ഞാൻ അംഗീകരിക്കുന്നു.', 'Initial text'),
  ('marketing', '1.0', 1, '', '', 'Sunrise may contact me (call, SMS or WhatsApp) about its health services and camps. Only my name, mobile number and city are used – never my medical details. I can withdraw this at any time.', 'സൺറൈസിന്റെ ആരോഗ്യ സേവനങ്ങളെയും ക്യാമ്പുകളെയും കുറിച്ച് എന്നെ ബന്ധപ്പെടാം (കോൾ, SMS, WhatsApp). എന്റെ പേര്, മൊബൈൽ നമ്പർ, നഗരം എന്നിവ മാത്രം – ചികിത്സാ വിവരങ്ങൾ ഒരിക്കലുമില്ല. എപ്പോൾ വേണമെങ്കിലും പിൻവലിക്കാം.', 'Initial text'),
  ('terms_of_use', '1.0', 1, 'Terms of Use', 'ഉപയോഗ നിബന്ധനകൾ', 'DRAFT – to be replaced by Sunrise Chain of Hospitals'' approved text.
insert into notification_templates (key, channel, provider_template_name, body_en, body_ml, variables, active, category, audience, channels, quiet_hours, sms_dlt_template_id, description) values
  ('otp', 'whatsapp', 'sunrise_otp_v1', 'Your Sunrise Care Connect OTP is {{otp}}. Valid for 5 minutes. Do not share it.', 'നിങ്ങളുടെ സൺറൈസ് കെയർ കണക്റ്റ് OTP {{otp}} ആണ്. 5 മിനിറ്റ് സാധുത. ആരുമായും പങ്കിടരുത്.', array['otp']::text[], false, 'auth', 'patient', array['sms']::notification_channel[], false, '1107000000000318916', 'Login code (sent by the auth service, not the outbox)'),
  ('booking_confirmed', 'whatsapp', 'sunrise_booking_confirmed_v1', 'Hi {{name}}, your Sunrise teleconsultation with {{doctor}} is confirmed for {{date}} at {{time}} IST. Ref {{ref}}. Details: {{link}}', 'നമസ്കാരം {{name}}, {{doctor}}-മായുള്ള നിങ്ങളുടെ സൺറൈസ് ടെലികൺസൾട്ടേഷൻ {{date}} {{time}}-ന് ഉറപ്പായി. റഫ് {{ref}}. വിവരങ്ങൾ: {{link}}', array['name','doctor','date','time','ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000293365294', 'Booking confirmed (paid or free)'),
  ('payment_received', 'whatsapp', 'sunrise_payment_received_v1', 'Payment of Rs {{amount}} received for booking {{ref}}. Your receipt is in the app: {{link}}', 'ബുക്കിംഗ് {{ref}}-ന് Rs {{amount}} ലഭിച്ചു. രസീത് ആപ്പിൽ: {{link}}', array['amount','ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000905256447', 'Payment receipt'),
  ('reminder_24h', 'whatsapp', 'sunrise_reminder_24h_v1', 'Reminder: your Sunrise teleconsultation {{ref}} is tomorrow, {{date}} at {{time}} IST. Details: {{link}}', 'ഓർമ്മപ്പെടുത്തൽ: നിങ്ങളുടെ സൺറൈസ് ടെലികൺസൾട്ടേഷൻ {{ref}} നാളെ, {{date}} {{time}}-ന്. വിവരങ്ങൾ: {{link}}', array['date','time','ref','link']::text[], true, 'reminder', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], true, '1107000002084677984', 'Reminder 24 hours before'),
  ('reminder_1h', 'whatsapp', 'sunrise_reminder_1h_v1', 'Reminder: your consultation {{ref}} starts at {{time}} IST. You can join from 10 minutes before: {{link}}', 'ഓർമ്മപ്പെടുത്തൽ: നിങ്ങളുടെ കൺസൾട്ടേഷൻ {{ref}} {{time}}-ന് ആരംഭിക്കും. 10 മിനിറ്റ് മുമ്പ് മുതൽ ചേരാം: {{link}}', array['ref','time','link']::text[], true, 'reminder', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000209847005', 'Reminder 1 hour before'),
  ('reminder_10m', 'whatsapp', 'sunrise_reminder_10m_v1', 'Your consultation {{ref}} starts in {{minutes}} minutes. Join here: {{link}}', 'നിങ്ങളുടെ കൺസൾട്ടേഷൻ {{ref}} {{minutes}} മിനിറ്റിനുള്ളിൽ ആരംഭിക്കും. ഇവിടെ ചേരുക: {{link}}', array['ref','minutes','link']::text[], true, 'reminder', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000002084679064', 'Join link 10 minutes before'),
  ('doctor_joined', 'whatsapp', 'sunrise_doctor_joined_v1', 'Your doctor is ready for consultation {{ref}}. Join now: {{link}}', 'കൺസൾട്ടേഷൻ {{ref}}-നായി ഡോക്ടർ തയ്യാറാണ്. ഇപ്പോൾ ചേരുക: {{link}}', array['ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000594573886', 'Join link when the doctor is in the room'),
  ('reschedule_proposed', 'whatsapp', 'sunrise_reschedule_proposed_v1', 'Your doctor has proposed a new time {{time}} IST today for booking {{ref}}. Please respond: {{link}}', 'ബുക്കിംഗ് {{ref}}-ന് ഇന്ന് {{time}}-ന് പുതിയ സമയം ഡോക്ടർ നിർദ്ദേശിച്ചു. മറുപടി നൽകുക: {{link}}', array['time','ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000960601812', 'Doctor asks to move the time'),
  ('rescheduled', 'whatsapp', 'sunrise_rescheduled_v1', 'Booking {{ref}} has been moved to {{date}} at {{time}} IST. Details: {{link}}', 'ബുക്കിംഗ് {{ref}} {{date}} {{time}}-ലേക്ക് മാറ്റി. വിവരങ്ങൾ: {{link}}', array['ref','date','time','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000619150989', 'Booking moved'),
  ('cancelled', 'whatsapp', 'sunrise_cancelled_v1', 'Booking {{ref}} for {{date}} has been cancelled. Details: {{link}}', 'ബുക്കിംഗ് {{ref}} ({{date}}) റദ്ദാക്കി. വിവരങ്ങൾ: {{link}}', array['ref','date','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000899006166', 'Cancelled by the patient or by Sunrise'),
  ('refund_initiated', 'whatsapp', 'sunrise_refund_initiated_v1', 'A refund of Rs {{amount}} for booking {{ref}} has been initiated. It usually reaches you in 5–7 working days. Details: {{link}}', 'ബുക്കിംഗ് {{ref}}-ന് Rs {{amount}} റീഫണ്ട് ആരംഭിച്ചു. 5–7 പ്രവൃത്തി ദിവസങ്ങൾക്കുള്ളിൽ ലഭിക്കും. വിവരങ്ങൾ: {{link}}', array['amount','ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000729790187', 'Refund started'),
  ('refund_processed', 'whatsapp', 'sunrise_refund_processed_v1', 'Your refund of Rs {{amount}} for booking {{ref}} has been sent to your bank / UPI. Details: {{link}}', 'ബുക്കിംഗ് {{ref}}-ന്റെ Rs {{amount}} റീഫണ്ട് നിങ്ങളുടെ ബാങ്ക് / UPI-ലേക്ക് അയച്ചു. വിവരങ്ങൾ: {{link}}', array['amount','ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000115982002', 'Refund completed by the gateway'),
  ('doctor_unavailable', 'whatsapp', 'sunrise_doctor_unavailable_v1', 'We are sorry, your doctor could not take booking {{ref}}. Choose a free reschedule or a full refund: {{link}}', 'ക്ഷമിക്കണം, ബുക്കിംഗ് {{ref}} ഡോക്ടർക്ക് എടുക്കാനായില്ല. സൗജന്യ റീഷെഡ്യൂൾ അല്ലെങ്കിൽ പൂർണ്ണ റീഫണ്ട് തിരഞ്ഞെടുക്കുക: {{link}}', array['ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000770096503', 'Doctor-side cancellation, no-show or technical failure'),
  ('consult_missed', 'whatsapp', 'sunrise_consult_missed_v1', 'Consultation {{ref}} did not take place. Book a free new time with the same doctor; a refund is available on request: {{link}}', 'കൺസൾട്ടേഷൻ {{ref}} നടന്നില്ല. അതേ ഡോക്ടറുമായി സൗജന്യമായി പുതിയ സമയം ബുക്ക് ചെയ്യുക; ആവശ്യപ്പെട്ടാൽ റീഫണ്ട് ലഭിക്കും: {{link}}', array['ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000260819477', 'Neither side joined'),
  ('prescription_ready', 'whatsapp', 'sunrise_prescription_ready_v1', 'Your consultation summary for {{ref}} is ready. View it securely in the app: {{link}}', '{{ref}}-ന്റെ കൺസൾട്ടേഷൻ സംഗ്രഹം തയ്യാറാണ്. ആപ്പിൽ സുരക്ഷിതമായി കാണുക: {{link}}', array['ref','link']::text[], true, 'transactional', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000001312714363', 'Prescription signed (no medicine or diagnosis in the message)'),
  ('follow_up_due', 'whatsapp', 'sunrise_follow_up_due_v1', 'Hi {{name}}, your free follow-up with {{doctor}} is available until {{date}}. Book: {{link}}', 'നമസ്കാരം {{name}}, {{doctor}}-മായുള്ള സൗജന്യ ഫോളോ-അപ്പ് {{date}} വരെ ലഭ്യമാണ്. ബുക്ക് ചെയ്യുക: {{link}}', array['name','doctor','date','link']::text[], true, 'reminder', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], true, '1107000001837689335', '2 days before the free follow-up window closes'),
  ('follow_up_advised', 'whatsapp', 'sunrise_follow_up_advised_v1', 'Hi {{name}}, {{doctor}} asked to see you again on {{date}}. Book your follow-up: {{link}}', 'നമസ്കാരം {{name}}, {{date}}-ന് വീണ്ടും കാണാൻ {{doctor}} നിർദ്ദേശിച്ചു. ഫോളോ-അപ്പ് ബുക്ക് ചെയ്യുക: {{link}}', array['name','doctor','date','link']::text[], true, 'reminder', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], true, '1107000001880028929', 'Day before the follow-up date the doctor set'),
  ('feedback_request', 'whatsapp', 'sunrise_feedback_request_v1', 'Hi {{name}}, how was your consultation with {{doctor}}? Tell us in one tap: {{link}}', 'നമസ്കാരം {{name}}, {{doctor}}-മായുള്ള കൺസൾട്ടേഷൻ എങ്ങനെയായിരുന്നു? ഒറ്റ ടാപ്പിൽ അറിയിക്കുക: {{link}}', array['name','doctor','link']::text[], true, 'service', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], true, '1107000001804354012', '2 hours after a completed consultation, if not rated'),
  ('doctor_new_booking', 'whatsapp', 'sunrise_doctor_new_booking_v1', 'New teleconsultation booked for {{date}} at {{time}} IST (ref {{ref}}). Open: {{link}}', '{{date}} {{time}}-ന് പുതിയ ടെലികൺസൾട്ടേഷൻ (റഫ് {{ref}}). തുറക്കുക: {{link}}', array['date','time','ref','link']::text[], true, 'transactional', 'doctor', array['sms','push','in_app']::notification_channel[], false, '1107000000755604961', 'Doctor: new booking'),
  ('doctor_booking_cancelled', 'whatsapp', 'sunrise_doctor_booking_cancelled_v1', 'Booking {{ref}} on {{date}} at {{time}} IST was cancelled. Open: {{link}}', '{{date}} {{time}}-നുള്ള ബുക്കിംഗ് {{ref}} റദ്ദാക്കി. തുറക്കുക: {{link}}', array['date','time','ref','link']::text[], true, 'transactional', 'doctor', array['sms','push','in_app']::notification_channel[], false, '1107000000964657966', 'Doctor: booking cancelled'),
  ('reschedule_response', 'whatsapp', 'sunrise_reschedule_response_v1', 'Patient responded to your reschedule request for {{ref}}: {{response}}. Open: {{link}}', '{{ref}}-നുള്ള റീഷെഡ്യൂൾ അഭ്യർത്ഥനയ്ക്ക് രോഗി മറുപടി നൽകി: {{response}}. തുറക്കുക: {{link}}', array['ref','response','link']::text[], true, 'transactional', 'doctor', array['sms','push','in_app']::notification_channel[], false, '1107000001613121455', 'Doctor: patient answered a reschedule'),
  ('ticket_update', 'whatsapp', 'sunrise_ticket_update_v1', 'Your support ticket {{ref}} has been updated. View: {{link}}', 'നിങ്ങളുടെ സപ്പോർട്ട് ടിക്കറ്റ് {{ref}} അപ്ഡേറ്റ് ചെയ്തു. കാണുക: {{link}}', array['ref','link']::text[], true, 'service', 'patient', array['whatsapp','sms','push','in_app']::notification_channel[], false, '1107000000401082549', 'Support ticket update');
